/* OakCrest skill quests: one short exercise for each skill on the skill map (assets/quests.js plays them). */
QUESTS.add({
"mt_kvrvpQris4":{"intro":"Let's use our words to share our feelings! 💬❤️","items":[{"t":"pick","q":"Your friend grabbed your toy. What is the best thing to do?","opts":["Say: I feel mad when you grab my toy.","hit your friend","scream and run away"],"why":"Words help others understand how you feel."},{"t":"sort","q":"Using words or acting out?","bins":["Using words 💬","Acting out"],"items":[["I feel sad because I lost.",0],["throwing the game",1],["telling a grown-up I'm upset",0],["hitting",1],["I feel angry when you yell.",0]]},{"t":"pick","q":"Which is an 'I feel' sentence?","opts":["I feel worried when it's dark.","You are mean!","Go away!"],"why":"An 'I feel' sentence names your feeling and why."},{"t":"tf","q":"It's okay to feel angry, but we should use words instead of hurting others.","a":true,"why":"All feelings are okay; how we act matters."},{"t":"do","q":"Mission: next time you feel upset, try saying 'I feel ___ because ___' to a grown-up."}]},
"mt_ggcamLzXAy":{"intro":"Feelings come and go, and everyone's are different! 🌈","items":[{"t":"tf","q":"Feelings can change during the day.","a":true,"why":"You might feel sleepy in the morning and happy at lunch."},{"t":"pick","q":"It starts to rain. Sam is sad he can't play outside. Ava is happy to splash in puddles. This shows…","opts":["the same thing can make people feel different ways","one of them is wrong","rain makes everyone sad"],"why":"Different people can feel differently about the same event."},{"t":"pick","q":"You feel sad now. Later, what might happen?","opts":["you might feel better","you will feel sad forever"],"why":"Feelings don't last forever."},{"t":"tf","q":"Everyone has feelings.","a":true,"why":"Kids, grown-ups, and friends all have feelings."},{"t":"do","q":"Mission: at bedtime, tell a grown-up two different feelings you had today and what made them change."}]},
"mt_LhkP_KKIRS":{"intro":"Let's name our feelings! 😀😢😠","items":[{"t":"match","q":"Match each face to its feeling.","pairs":[["😀","happy"],["😢","sad"],["😠","angry"],["😨","scared"]]},{"t":"match","q":"Match each face to its feeling.","pairs":[["😲","surprised"],["🤩","excited"],["😀","happy"]]},{"t":"pick","q":"Your friend is crying and looking down. How might they feel?","opts":["sad","excited","silly"],"why":"Tears and looking down often mean sad."},{"t":"pick","q":"Your heart beats fast and you want to hide from a loud noise. You feel…","opts":["scared","happy","bored"],"why":"Our bodies give clues about feelings."},{"t":"do","q":"Mission: make a happy face, a sad face, and a surprised face in a mirror. Can a grown-up guess each one?"}]},
"mt_9Y5-GjF2B0":{"intro":"Feelings have causes! Let's find them! 🔍❤️","items":[{"t":"match","q":"Match what happened to how someone might feel.","pairs":[["got a birthday present 🎁","happy"],["lost a favorite toy","sad"],["heard thunder at night ⛈️","scared"],["someone knocked over their tower","angry"]]},{"t":"pick","q":"Finish the sentence: I felt proud because…","opts":["I learned to ride my bike","I dropped my ice cream","I lost my shoe"],"why":"Doing something hard can make us feel proud."},{"t":"pick","q":"In a story, the dog runs away and the girl cries. What made her sad?","opts":["her dog ran away","she ate lunch","it was sunny"],"why":"The trigger was her dog running away."},{"t":"tf","q":"A trigger is something that happens that causes a feeling.","a":true,"why":"Knowing triggers helps us understand our feelings."},{"t":"do","q":"Mission: tell a grown-up one thing that makes you happy and one thing that makes you upset. Say 'I feel ___ because ___.'"}]},
"mt_MOY_2Cqalz":{"intro":"Let's grow our feelings vocabulary! 📚💭","items":[{"t":"match","q":"Match each feeling word to a situation.","pairs":[["embarrassed","tripping in front of the class"],["jealous","wishing you had your friend's new bike"],["grateful","thankful for help"],["lonely","no one to play with"]]},{"t":"pick","q":"Your puzzle piece won't fit, and you've tried 10 times. The best word is…","opts":["frustrated","grateful","proud"],"why":"Frustrated means upset when something keeps not working."},{"t":"pick","q":"What's the difference between disappointed and angry?","opts":["disappointed is sad that something didn't happen; angry is mad","they mean exactly the same thing","angry is a happy feeling"],"why":"Choosing the precise word helps others understand."},{"t":"pick","q":"You keep thinking about tomorrow's test and your tummy feels tight. You feel…","opts":["worried","bored","jealous"],"why":"Worried means thinking something bad might happen."},{"t":"do","q":"Mission: today, use two new feeling words, like proud or frustrated, to tell a grown-up how you felt."}]},
"mt_E5ju6kQSu3":{"intro":"Let's be feeling detectives and look for feelings that are hiding! 🕵️","items":[{"t":"pick","q":"Maya says \"I'm fine\" 🙂 but her eyes are down and her voice is very quiet. What might be true?","opts":["She may be sad but hiding it","She is definitely very happy","She is feeling silly"],"why":"Her words say fine, but her body and voice show she may be sad."},{"t":"tf","q":"People sometimes smile even when they feel sad inside.","a":true,"why":"Lots of people hide their feelings. A smile does not always mean happy."},{"t":"pick","q":"Why might a kid hide feeling scared before a race? 🏃","opts":["They don't want others to see them worried","Because being scared is against the rules","Because they forgot how to feel"],"why":"People often hide feelings so others won't notice or worry."},{"t":"sort","q":"Do the words and the body match, or not match?","bins":["Match","Don't match"],"items":[["\"I'm so happy!\" with a big real smile 😄",0],["\"I'm not mad!\" with crossed arms and a frown 😠",1],["\"I'm okay\" while wiping away tears 😢",1],["\"I'm tired\" with a big yawn 🥱",0]],"why":"When words and body don't match, the body often shows the real feeling."},{"t":"do","q":"Mission: think of a time you said \"I'm fine\" when you weren't. Tell a grown-up why you hid it, and talk about who you could share real feelings with."}]},
"mt_Ytd8XC3eQr":{"intro":"Our bodies send us feeling signals. Let's learn to read them! 💓","items":[{"t":"match","q":"Match each body signal to the feeling it often shows.","pairs":[["butterflies in your tummy 🦋","nervous"],["clenched fists ✊","angry"],["tight, stiff shoulders","stressed"],["warm, relaxed body 😌","calm"]]},{"t":"pick","q":"Your heart is racing as the roller coaster climbs up 🎢. Which feelings could cause this?","opts":["Scared or excited","Bored or sleepy","Calm and relaxed"],"why":"A racing heart can come from fear or excitement."},{"t":"tf","q":"When you are angry, your face might feel hot.","a":true,"why":"Anger can make your face feel hot and red."},{"t":"pick","q":"Why does your body react when you feel scared?","opts":["It gets ready to run or protect you","It wants you to fall asleep","It is trying to make you hungry"],"why":"Your body gets ready for action to keep you safe."},{"t":"do","q":"Mission: next time you feel a big feeling, stop and notice your body. Where do you feel it? Tell a grown-up the body clue and the feeling."}]},
"mt_rymBfJmvFl":{"intro":"Feelings can be small, medium, or BIG. Let's measure them! 🌡️","items":[{"t":"order","q":"Put these from mildest to strongest.","steps":["annoyed","angry","furious"]},{"t":"order","q":"Put these from mildest to strongest.","steps":["nervous","anxious","panicked"]},{"t":"pick","q":"Which word shows the strongest happy feeling? 🎉","opts":["overjoyed","content","pleased"],"why":"Overjoyed is a huge happy feeling. Content is gentle."},{"t":"tf","q":"Feeling a little annoyed and feeling furious need the same plan to calm down.","a":false,"why":"Bigger feelings often need bigger calming plans, like taking a break."},{"t":"do","q":"Mission: make a feelings scale from 1 to 5 with a grown-up. Rate how you feel right now, and once more later today."}]},
"mt_nIl1kKZHsk":{"intro":"Why do two people feel differently about the same thing? Let's find out! 🌍","items":[{"t":"pick","q":"A dog runs up to two kids 🐕. Sam smiles; Leo freezes in fear. What is the most likely reason?","opts":["Leo may have been bitten or scared by a dog before","Sam's feelings are right and Leo's are wrong","Dogs only like one person"],"why":"Past experiences shape how we feel in a situation."},{"t":"tf","q":"The same event can make different people feel different emotions.","a":true,"why":"Our backgrounds, culture, and memories shape our feelings."},{"t":"pick","q":"In some families, people show feelings loudly; in others, quietly. This difference often comes from…","opts":["culture and family habits","eye color","the weather"],"why":"Culture teaches us ways of showing and handling feelings."},{"t":"sort","q":"Which things can shape how someone feels about an event?","bins":["Can shape feelings","Does not shape feelings"],"items":[["past experiences",0],["family traditions",0],["the culture they grew up in",0],["their shoe size",1],["the color of their backpack",1]]},{"t":"pick","q":"A classmate cries over something that seems small to you. What's the kindest thought?","opts":["It may matter more to them for reasons I don't know","They are just being silly","They should feel the same as me"],"why":"Remembering people have different backgrounds helps us be kind."}]},
"mt_cEQqskOaoo":{"intro":"Let's become scientists of our own feelings and look for patterns! 📈","items":[{"t":"pick","q":"Jada gets grumpy every day right before lunch 🍽️. What pattern might explain it?","opts":["She feels grumpy when she's hungry","She hates Tuesdays","Grumpiness is random"],"why":"Noticing when feelings repeat helps you find triggers like hunger."},{"t":"pick","q":"Something that often sets off a strong feeling is called a…","opts":["trigger","habit","mood ring"],"why":"A trigger is something that sparks a feeling or reaction."},{"t":"tf","q":"Keeping a feelings journal for a few weeks can help you spot your patterns.","a":true,"why":"Writing it down shows what repeats over time."},{"t":"tf","q":"How you handle feelings can change and get better as you grow.","a":true,"why":"With practice, people learn new ways to respond."},{"t":"do","q":"Mission: for one week, write or draw one feeling each evening and what came before it. At the end, look for a pattern with a grown-up."}]},
"mt_KA5j5OeGvw":{"intro":"Big feelings can steer our choices. Let's learn to take the wheel! 🚗","items":[{"t":"pick","q":"Alex is furious and wants to send a mean text right away 📱. What's the wisest choice?","opts":["Wait until calm, then decide","Send it fast before the anger fades","Send it to everyone"],"why":"Strong feelings can cloud judgment. Calm choices are usually better."},{"t":"tf","q":"People often make different choices when they are calm than when they are upset.","a":true,"why":"Strong emotions can make it hard to think clearly."},{"t":"pick","q":"You're super excited about a game and want to spend all your saved money on it right now. What might help?","opts":["Sleep on it and decide tomorrow","Buy it before you think","Borrow more money too"],"why":"Waiting lets excitement settle so you can think it through."},{"t":"tf","q":"Emotions are always bad for decision-making.","a":false,"why":"Feelings give useful information, like fear warning of danger. We just need to think too."},{"t":"order","q":"Put these steps for a big-feeling decision in order.","steps":["Notice the strong feeling","Pause and breathe","Think about the choices","Make a calm decision"]}]},
"mt_dlm3NspUyy":{"intro":"Can you feel two things at once? Yes! Let's explore mixed feelings. 🎭","items":[{"t":"pick","q":"Starting at a new school, Ava feels excited AND nervous 🏫. This is called…","opts":["mixed feelings","no feelings","a mistake"],"why":"Feeling two emotions at once is called mixed feelings, and it's normal."},{"t":"tf","q":"You can feel happy and sad at the same time.","a":true,"why":"For example, happy to move to a new home but sad to leave friends."},{"t":"match","q":"Match each situation to the mixed feelings it might bring.","pairs":[["best friend moving away, but you get to visit","sad and hopeful"],["winning a prize your friend wanted","proud and guilty"],["your first time on stage 🎤","excited and scared"]]},{"t":"pick","q":"What is a helpful way to handle mixed feelings?","opts":["Name both feelings and talk about them","Pretend you only feel one","Ignore all your feelings"],"why":"Naming each feeling helps you understand yourself."},{"t":"do","q":"Mission: think of a time you had two feelings at once. Draw a picture split in half showing both, and share it with a grown-up."}]},
"mt_gf4RUcACLg":{"intro":"Let's peek inside the brain and see how feelings work! 🧠","items":[{"t":"match","q":"Match each brain part to its job.","pairs":[["amygdala","sounds the alarm for strong emotions"],["prefrontal cortex","plans, thinks, and calms responses"],["hippocampus","helps store memories"]]},{"t":"tf","q":"The prefrontal cortex keeps developing into a person's mid-twenties.","a":true,"why":"That's one reason teens can find strong feelings harder to manage."},{"t":"pick","q":"When the amygdala reacts before the thinking brain catches up, people may…","opts":["react quickly without thinking it through","always make perfect choices","stop feeling anything"],"why":"The alarm is fast; the thinking brain is slower."},{"t":"pick","q":"Which strategy helps the thinking brain catch up during a big feeling?","opts":["Slow deep breaths and a pause","Yelling louder","Making a choice instantly"],"why":"Pausing and breathing gives the prefrontal cortex time to work."},{"t":"tf","q":"The amygdala's job is to help solve math problems.","a":false,"why":"The amygdala detects threats and triggers emotions like fear."}]},
"mt_p-8Hlf6_9k":{"intro":"Who am I? Let's explore identity and belonging. 🪞","items":[{"t":"pick","q":"During the teen years, many people ask \"Who am I?\" This is part of…","opts":["building your identity","forgetting who you are","something only adults do"],"why":"Teens actively shape their identity, which can bring big feelings."},{"t":"tf","q":"It's normal for interests and friend groups to change as you grow up.","a":true,"why":"Exploring and changing is a healthy part of finding yourself."},{"t":"pick","q":"Riley wants to fit in so badly that she pretends to hate a hobby she loves. What might this cause?","opts":["Feeling torn between belonging and being herself","Feeling more like herself","Nothing at all"],"why":"Hiding who you are to belong can feel uncomfortable inside."},{"t":"sort","q":"Which are parts of a person's identity?","bins":["Part of identity","Not really identity"],"items":[["your values",0],["your culture and family",0],["your interests",0],["today's weather",1],["what's for lunch",1]]},{"t":"pick","q":"Which is a healthy way to belong?","opts":["Find people who accept the real you","Change everything to match others","Avoid all groups forever"],"why":"True belonging means you don't have to hide who you are."}]},
"mt_mydcMoa8gN":{"intro":"Emotional intelligence is a superpower you can grow! 💡","items":[{"t":"match","q":"Match each part of emotional intelligence to its meaning.","pairs":[["self-awareness","knowing your own feelings"],["self-regulation","managing your feelings"],["empathy","understanding others' feelings"],["social skills","getting along with others"]]},{"t":"pick","q":"Nora keeps practicing piano because she loves getting better, not for prizes. Which part of emotional intelligence is this?","opts":["motivation","empathy","social skills"],"why":"Motivation means driving yourself toward goals."},{"t":"pick","q":"Which word means feeling a bit sad and thoughtful, like missing old times?","opts":["nostalgic","furious","ecstatic"],"why":"Nostalgic means fondly missing the past."},{"t":"tf","q":"Emotional intelligence is fixed at birth and cannot improve.","a":false,"why":"These skills can be learned and practiced."},{"t":"pick","q":"Your friend seems quiet after a test. A high-empathy response is…","opts":["\"You seem down. Want to talk?\"","\"Cheer up, it's nothing.\"","Ignoring them"],"why":"Empathy means noticing and caring about how others feel."}]},
"mt_lAvS72LOUO":{"intro":"Small kind acts make a big difference! 💛","items":[{"t":"pick","q":"A friend drops all their crayons on the floor 🖍️. What is a kind thing to do?","opts":["Help pick them up","Laugh at them","Walk away"],"why":"Helping someone shows you care."},{"t":"sort","q":"Kind or not kind?","bins":["Kind 💛","Not kind"],"items":[["sharing your snack 🍎",0],["hugging a sad friend",0],["pushing in line",1],["saying \"thank you\"",0],["taking someone's toy",1]]},{"t":"pick","q":"Your friend is crying 😢. What could you say?","opts":["\"Are you okay? Can I help?\"","\"Stop crying!\"","\"Go away.\""],"why":"Asking if they are okay shows care."},{"t":"tf","q":"Being kind can make you feel good too.","a":true,"why":"Kindness helps others and warms your own heart."},{"t":"do","q":"Mission: do one kind thing today for someone at home, like helping set the table. Tell a grown-up how it felt."}]},
"mt_wzUzVEBqJb":{"intro":"Everyone has their own thoughts and feelings inside! 💭","items":[{"t":"tf","q":"My friend always likes the same things I like.","a":false,"why":"Other people can like different things than you."},{"t":"pick","q":"You love spicy food 🌶️. Your friend does not. What is true?","opts":["Your friend has a different taste","Your friend is wrong","Your friend is being mean"],"why":"People can like different things, and that's okay."},{"t":"pick","q":"Ben gets a new puppy 🐶 and is happy. You are sad because your toy broke. What is true?","opts":["You both can have different feelings at once","Ben should feel sad too","You should feel happy too"],"why":"Different people can feel different things at the same time."},{"t":"pick","q":"How can you find out what your friend is thinking?","opts":["Ask them","Guess and never ask","Look at your own toes"],"why":"Asking helps us learn what others think and feel."},{"t":"do","q":"Mission: ask a family member what their favorite food is. Is it the same as yours or different?"}]},
"mt_OJVkWvIaM_":{"intro":"People are alike in some ways and different in others! 🌈","items":[{"t":"tf","q":"Families can look different. Some have one parent, two parents, grandparents, or other caring grown-ups.","a":true,"why":"There are many kinds of families, and all can be loving."},{"t":"pick","q":"Mia speaks Spanish at home and you speak English. What does this show?","opts":["People can speak different languages","Only one language is right","Mia is strange"],"why":"People around the world speak many languages."},{"t":"sort","q":"Is this something all people share, or something that can be different?","bins":["All people share","Can be different"],"items":[["needing food and water 💧",0],["favorite food",1],["having feelings",0],["language spoken at home",1],["hair color",1]]},{"t":"pick","q":"What is a good way to treat differences?","opts":["Be curious and respectful","Make fun of them","Pretend they aren't there"],"why":"Differences make the world interesting."},{"t":"do","q":"Mission: find one way you and a friend or family member are the same and one way you are different. Share them out loud."}]},
"mt_wRlf0g2MbB":{"intro":"Let's learn words that help us understand others! 📚","items":[{"t":"match","q":"Match each word to what it means.","pairs":[["empathy","understanding how someone else feels"],["fair","everyone gets treated right"],["similar","almost the same"],["community","a group of people who live or work together"]]},{"t":"pick","q":"\"I wonder how it looks from her side.\" This is thinking about her…","opts":["perspective","dinner","shoes"],"why":"Perspective means how someone sees things."},{"t":"pick","q":"Which word fits? \"A cat and a lion are ___ because they are both cats.\"","opts":["similar","different","unfair"],"why":"Similar means alike in some ways."},{"t":"tf","q":"Care means showing that you want someone to be okay.","a":true,"why":"Caring means looking out for others."},{"t":"pick","q":"Which one shows being kind?","opts":["Inviting a new kid to play","Ignoring a new kid","Taking the new kid's seat"],"why":"Kind means being friendly and helpful."}]},
"mt_S7UTAhptLi":{"intro":"Every person has a life story. Let's learn about different lives! 🧭","items":[{"t":"tf","q":"Some kids face challenges, like having less money at home or caring for a sick family member.","a":true,"why":"People's lives can be very different from our own."},{"t":"pick","q":"A classmate uses a wheelchair ♿. What is the respectful thing to do?","opts":["Include them and ask if they want help","Decide what they can't do","Stare at them"],"why":"Including others and asking respects them."},{"t":"pick","q":"A friend can't come to a party because their family can't afford a gift. What could help?","opts":["Say gifts aren't needed, just come!","Tease them","Tell everyone"],"why":"Being thoughtful helps people feel included."},{"t":"tf","q":"If someone's life is different from yours, their life must be worse.","a":false,"why":"Different doesn't mean worse. Every life has its own strengths."},{"t":"do","q":"Mission: read or listen to a story about a child whose life is different from yours. Tell a grown-up one thing you learned."}]},
"mt_mDp-1vlL3R":{"intro":"Is fair always the same as equal? Let's find out! ⚖️","items":[{"t":"pick","q":"Three kids want to see over a fence. Giving each one the same size box is called…","opts":["equality","equity","friction"],"why":"Equality means everyone gets the same thing."},{"t":"pick","q":"Giving each kid the box size they need so all can see is called…","opts":["equity","equality","luck"],"why":"Equity means giving people what they need to have a fair chance."},{"t":"tf","q":"Glasses for a student who can't see the board is fair, even if other kids don't get glasses.","a":true,"why":"Fair can mean giving people what they need."},{"t":"sort","q":"Equal (everyone the same) or equitable (what each person needs)?","bins":["Equal","Equitable"],"items":[["every kid gets 2 cookies 🍪",0],["a ramp for a wheelchair user",1],["extra help for a student learning English",1],["everyone gets the same worksheet",0]]},{"t":"pick","q":"Why does fairness matter?","opts":["It helps everyone feel respected","It means someone always wins","It isn't important"],"why":"Fairness builds trust and respect."}]},
"mt_9NQEiYLQA3":{"intro":"Let's step into someone else's shoes! 👟","items":[{"t":"pick","q":"Zoe was picked last for a team. How might she feel?","opts":["left out and sad","proud and excited","sleepy"],"why":"Being picked last can make someone feel left out."},{"t":"pick","q":"Which question helps you see someone else's point of view?","opts":["\"How would I feel if that happened to me?\"","\"Why should I care?\"","\"What's for lunch?\""],"why":"Imagining yourself in their place builds understanding."},{"t":"tf","q":"Two people can see the same event in different ways.","a":true,"why":"Each person has their own point of view."},{"t":"pick","q":"Your little brother knocked over your tower by accident and looks scared. What is he probably thinking?","opts":["\"Oh no, they'll be mad at me!\"","\"I'm so happy!\"","\"I want to knock it again.\""],"why":"Thinking about his side helps you respond kindly."},{"t":"do","q":"Mission: during a story or show today, pause and ask, \"How does this character feel? Why?\" Talk about it with a grown-up."}]},
"mt_a6AYrbb7x4":{"intro":"Big words help us talk about fairness. Let's learn them! 🗣️","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["stereotype","a fixed idea that all people in a group are the same"],["prejudice","judging someone before knowing them"],["discrimination","treating someone unfairly because of who they are"],["compassion","caring and wanting to help someone who is hurting"]]},{"t":"pick","q":"\"All girls are bad at sports\" is an example of a…","opts":["stereotype","compliment","fact"],"why":"It's an oversimplified idea about a whole group."},{"t":"pick","q":"Leaning toward one side without good reason is called…","opts":["bias","equity","respect"],"why":"Bias means an unfair leaning for or against something."},{"t":"tf","q":"Equity means giving everyone exactly the same thing.","a":false,"why":"That's equality. Equity means giving people what they need."},{"t":"pick","q":"A store refuses to hire someone because of their religion. This is…","opts":["discrimination","fairness","compassion"],"why":"Treating people unfairly because of identity is discrimination."}]},
"mt_HFN1pGASpZ":{"intro":"Let's understand how unfair treatment hurts, and how to help. 🤝","items":[{"t":"pick","q":"Kids won't let Omar play because he speaks with an accent. This is…","opts":["discrimination","teamwork","a fair rule"],"why":"Treating him unfairly because of who he is is discrimination."},{"t":"tf","q":"Prejudice can hurt a whole community, not just one person.","a":true,"why":"It can make many people feel unsafe or unwelcome."},{"t":"pick","q":"How might someone feel after facing discrimination?","opts":["hurt, angry, or left out","proud and included","nothing at all"],"why":"Unfair treatment causes real hurt."},{"t":"pick","q":"You hear a classmate make a mean joke about someone's culture. What is a helpful choice?","opts":["Say \"That's not okay\" and tell a trusted adult","Laugh along","Repeat it to others"],"why":"Speaking up and getting help can stop harm."},{"t":"sort","q":"Prejudice or respect?","bins":["Prejudice","Respect"],"items":[["deciding you won't like someone because of their skin color",0],["learning about a friend's holiday",1],["inviting everyone to play",1],["assuming an older person can't use a phone",0]]}]},
"mt_cOknxrYhwL":{"intro":"Our brains make quick guesses. Let's learn to double-check them! 🔍","items":[{"t":"tf","q":"Everyone has some assumptions about others, even without meaning to.","a":true,"why":"These are called unconscious biases. Noticing them is the first step."},{"t":"pick","q":"You assume the new kid in fancy clothes is snobby. What should you do?","opts":["Get to know them before judging","Avoid them forever","Tell others they're snobby"],"why":"Questioning your first guess can prove it wrong."},{"t":"pick","q":"Which question helps you check a bias?","opts":["\"What makes me think that? Is it really true?\"","\"Who agrees with me?\"","\"How can I prove I'm right?\""],"why":"Asking what your idea is based on helps you see bias."},{"t":"tf","q":"If you have a bias, it means you are a bad person.","a":false,"why":"Everyone has biases. What matters is noticing and questioning them."},{"t":"do","q":"Mission: think of a time you guessed something about someone and were wrong. Talk with a grown-up about what you learned."}]},
"mt_2oswCNuapH":{"intro":"Every person is one of a kind. Let's spot stereotypes! 🦓","items":[{"t":"pick","q":"What is a stereotype?","opts":["An oversimplified belief about a whole group","A fact proven by science","A type of music player"],"why":"Stereotypes treat everyone in a group as the same."},{"t":"sort","q":"Stereotype or fair statement?","bins":["Stereotype","Fair statement"],"items":[["\"Boys don't cry.\"",0],["\"Old people can't learn new tech.\"",0],["\"Some people like science and some don't.\"",1],["\"Each person has their own strengths.\"",1],["\"Girls can't build things.\"",0]]},{"t":"tf","q":"Stereotypes can be harmful even when they sound positive, like \"all kids from one place are good at math.\"","a":true,"why":"They still ignore that every person is an individual."},{"t":"pick","q":"Why are stereotypes unfair?","opts":["They ignore each person's real differences","They are always about sports","They are too short"],"why":"People within any group are all different."},{"t":"pick","q":"A friend says \"Girls aren't good at video games.\" What's a good reply?","opts":["\"Lots of girls are great gamers. It depends on the person.\"","\"You're right.\"","Say nothing and agree"],"why":"Challenging stereotypes kindly helps change minds."}]},
"mt_DkzsZdyaL2":{"intro":"Let's travel the world and discover different cultures! 🌏","items":[{"t":"match","q":"Match each celebration to the tradition it's known for.","pairs":[["Diwali","lighting lamps for the festival of lights 🪔"],["Lunar New Year","red envelopes and dragon dances 🐉"],["Thanksgiving","a big family feast 🦃"],["Hanukkah","lighting a menorah for eight nights 🕎"]]},{"t":"tf","q":"Learning about other cultures can help us understand the world better.","a":true,"why":"Other perspectives add to our own understanding."},{"t":"pick","q":"Your friend's family takes off shoes at the door 👟. What's the respectful thing to do?","opts":["Take yours off too","Tell them it's weird","Keep them on anyway"],"why":"Respecting others' customs shows care."},{"t":"pick","q":"Which is the best way to learn about a friend's culture?","opts":["Ask them kindly and listen","Guess and assume","Make jokes about it"],"why":"Curious, respectful questions help you learn."},{"t":"tf","q":"There is only one right way to celebrate holidays.","a":false,"why":"People celebrate in many wonderful ways."}]},
"mt_oqvJJKCJXw":{"intro":"Let's look at how systems can be unfair, and how allies help. 🏗️","items":[{"t":"pick","q":"A school has only stairs, so a student using a wheelchair can't reach the library. This is an example of…","opts":["a structural barrier","a personal choice","a fair rule"],"why":"The building itself creates the disadvantage, not the student's effort."},{"t":"tf","q":"Some people face disadvantages even if they work just as hard as others.","a":true,"why":"Structures and systems can give some people advantages and others obstacles."},{"t":"pick","q":"What does an ally do?","opts":["Uses their voice to support people facing unfairness","Stays silent to stay comfortable","Speaks over the people affected"],"why":"Allies listen and stand up alongside others."},{"t":"pick","q":"Why might \"treating everyone the same\" not fix inequality?","opts":["People start from different places with different barriers","Everyone is already equal","Rules never matter"],"why":"Removing barriers sometimes needs different support."},{"t":"sort","q":"Helpful allyship or not helpful?","bins":["Helpful allyship","Not helpful"],"items":[["listening to people's experiences",0],["speaking up when you see unfairness",0],["saying \"I don't see any problem\" without listening",1],["taking credit for others' ideas",1]]}]},
"mt_VA126P6Wp5":{"intro":"Sympathy and empathy are different. Let's learn the difference! 👂","items":[{"t":"sort","q":"Is it sympathy or empathy?","bins":["Sympathy","Empathy"],"items":[["\"I feel sorry for you.\"",0],["\"That sounds really hard. I'm here.\"",1],["\"Oh, poor you.\"",0],["\"It sounds like you felt left out.\"",1]]},{"t":"pick","q":"Repeating back what someone said in your own words is called…","opts":["paraphrasing","interrupting","lecturing"],"why":"Paraphrasing shows you truly heard them."},{"t":"pick","q":"A friend says their pet died. Which reply shows active listening?","opts":["\"You must really miss her. Want to tell me about her?\"","\"At least you can get a new one.\"","\"My cat is fine.\""],"why":"Reflecting feelings and inviting them to share shows empathy."},{"t":"tf","q":"Empathy means understanding what someone is going through, not just feeling sorry for them.","a":true,"why":"Empathy is feeling with someone; sympathy is feeling for them."},{"t":"pick","q":"Which is a sign of good active listening?","opts":["Making eye contact and not interrupting","Checking your phone","Planning your reply while they talk"],"why":"Full attention shows you care."}]},
"mt_5XLhiqmocP":{"intro":"We're all connected around the world. Let's be global citizens! 🌐","items":[{"t":"pick","q":"What is a global citizen?","opts":["Someone who knows choices affect people worldwide","Someone who has visited every country","Someone who only cares about their town"],"why":"Global citizens think about how the world is connected."},{"t":"tf","q":"Pollution made in one country can affect people in other countries.","a":true,"why":"Air, oceans, and climate are shared by everyone."},{"t":"pick","q":"Your new T-shirt was made in another country. This shows…","opts":["countries are connected by trade","shirts grow on trees","only one country makes clothes"],"why":"Goods travel across the world, linking people."},{"t":"sort","q":"Which are global issues?","bins":["Global issue","Mostly local"],"items":[["climate change",0],["ocean plastic",0],["access to clean water worldwide",0],["a broken swing at your park",1],["your school's lunch menu",1]]},{"t":"pick","q":"Which action shows global citizenship?","opts":["Learning about an issue and acting responsibly","Ignoring world news","Wasting water"],"why":"Small choices, like saving water, can add up worldwide."}]},
"mt_PdYlsA33jB":{"intro":"Asking for help is brave and smart! 🙋","items":[{"t":"tf","q":"Asking for help means you are weak.","a":false,"why":"Asking for help is a sign of strength."},{"t":"pick","q":"You can't open your lunch box 🍱. What can you do?","opts":["Ask, \"Can you please help me?\"","Cry and give up","Throw it"],"why":"Asking politely gets you the help you need."},{"t":"sort","q":"Who can you ask for help?","bins":["Good helper","Not a good choice"],"items":[["your teacher 👩‍🏫",0],["a parent or family member",0],["a friend",0],["a stranger in a car",1]]},{"t":"pick","q":"Which is a good way to ask for help?","opts":["\"Excuse me, can you help me with this?\"","\"Do this for me NOW!\"","Grab their arm and pull"],"why":"Using kind words makes people happy to help."},{"t":"do","q":"Mission: next time something is tricky, try asking a grown-up, \"Can you please help me?\" Notice how it feels."}]},
"mt_YbX3LD0Eca":{"intro":"Good listeners use their eyes, ears, and kind hearts! 👂","items":[{"t":"sort","q":"Good listening or not?","bins":["Good listening","Not listening"],"items":[["looking at the speaker 👀",0],["waiting until they finish",0],["talking at the same time",1],["playing with a toy while they talk",1],["nodding your head",0]]},{"t":"pick","q":"Your friend tells you about their new kitten 🐱. What shows you listened?","opts":["\"What's your kitten's name?\"","\"I like pizza.\"","Walking away"],"why":"Asking about what they said shows you heard them."},{"t":"tf","q":"Interrupting someone shows good listening.","a":false,"why":"Good listeners wait their turn to talk."},{"t":"pick","q":"Where should your eyes be when someone is talking to you?","opts":["On the speaker","On the ceiling","Closed"],"why":"Looking at the speaker shows you care."},{"t":"do","q":"Mission: at dinner, listen to someone tell about their day without interrupting. Then ask one question about it."}]},
"mt_HBcvu0UxYe":{"intro":"What makes a good friend? Let's find out! 🤗","items":[{"t":"sort","q":"Good friend or not friendly?","bins":["Good friend 😊","Not friendly"],"items":[["sharing toys",0],["telling the truth",0],["leaving someone out on purpose",1],["calling names",1],["asking someone to join your game",0]]},{"t":"pick","q":"A good friend is…","opts":["kind and honest","bossy and mean","always grabbing toys"],"why":"Good friends are kind, honest, and fair."},{"t":"tf","q":"A good friend keeps their promises.","a":true,"why":"Being reliable means friends can trust you."},{"t":"pick","q":"A new kid is standing alone at recess. What would a good friend do?","opts":["Invite them to play","Laugh at them","Ignore them"],"why":"Including others is what good friends do."},{"t":"do","q":"Mission: tell a friend or family member one thing you like about them."}]},
"mt_FwI7q7DSIx":{"intro":"Taking turns and sharing make games more fun! 🎲","items":[{"t":"pick","q":"There is one swing and two kids want it. What's a fair idea?","opts":["Take turns","Push the other kid off","Stay on it all day"],"why":"Taking turns lets everyone play."},{"t":"tf","q":"Games work better when everyone gets a turn.","a":true,"why":"Fair turns keep everyone happy."},{"t":"pick","q":"You have 4 crayons 🖍️ and your friend has 0. What is a kind way to share?","opts":["Give your friend 2","Keep all 4","Hide them"],"why":"Sharing equally is fair: 2 and 2."},{"t":"pick","q":"It's not your turn yet in a board game. What do you do?","opts":["Wait patiently","Grab the dice","Quit the game"],"why":"Waiting your turn shows good cooperation."},{"t":"do","q":"Mission: play a game with someone at home and practice saying, \"Your turn!\""}]},
"mt_NS5t-Jzlh8":{"intro":"Let's learn teamwork words! 🧩","items":[{"t":"match","q":"Match each word to what it means.","pairs":[["cooperate","work together"],["include","let someone join in"],["take turns","go one after another"],["team","a group working toward the same goal"]]},{"t":"pick","q":"Which is a respectful way to disagree?","opts":["\"I see it differently. Can I share my idea?\"","\"Your idea is dumb!\"","Stomping away"],"why":"You can disagree and still be kind."},{"t":"pick","q":"\"We both think pizza is best!\" This means you…","opts":["agree","disagree","argue"],"why":"Agree means you think the same."},{"t":"tf","q":"Share means letting others use something too.","a":true,"why":"Sharing means letting others have a turn with something."},{"t":"pick","q":"Which word fits? \"Please ___ while I explain the rules.\"","opts":["listen","shout","run"],"why":"Listening helps teams understand each other."}]},
"mt_Ag9NSWJu-X":{"intro":"Let's learn words that help us talk through problems! 💬","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["assertive","saying what you need clearly and kindly"],["passive","not speaking up for yourself"],["aggressive","being pushy or hurtful"],["compromise","each side gives a little to agree"]]},{"t":"pick","q":"Someone who helps two others solve a conflict is called a…","opts":["mediator","bystander","competitor"],"why":"A mediator helps others find a solution."},{"t":"pick","q":"\"I'd like a turn now, please.\" This is…","opts":["assertive","aggressive","passive"],"why":"It's clear and respectful."},{"t":"tf","q":"A bystander is someone who sees something happen but isn't directly involved.","a":true,"why":"Bystanders watch; upstanders take action to help."},{"t":"pick","q":"When a conflict is solved, we call that a…","opts":["resolution","conflict","aggression"],"why":"Resolution means finding an answer to a problem."}]},
"mt_X7Tu94-a2m":{"intro":"Friendships grow and change, and that's okay! 🌱","items":[{"t":"tf","q":"It's normal for friends to drift apart sometimes.","a":true,"why":"People change interests and classes, and friendships can change too."},{"t":"pick","q":"Your best friend is now spending more time with a new group. What's a healthy thought?","opts":["\"It's okay. I can make new friends too.\"","\"Nobody will ever like me.\"","\"I should be mean to them.\""],"why":"Change can be sad, but new friendships can grow."},{"t":"pick","q":"Which is a good way to make a new friend?","opts":["Join a club and say hi to someone","Wait for someone to find you","Only talk online to strangers"],"why":"Shared activities help friendships start."},{"t":"tf","q":"If a friendship changes, it means you did something wrong.","a":false,"why":"Friendships change for many reasons, often no one's fault."},{"t":"do","q":"Mission: think of someone you'd like to get to know better. Plan one friendly thing to say to them this week."}]},
"mt_iWGnyUyN2j":{"intro":"Disagreements happen. Let's learn to talk them out! 🗨️","items":[{"t":"order","q":"Put these steps for solving a disagreement in order.","steps":["Calm down","Say how you feel","Listen to the other person","Find a compromise together"]},{"t":"pick","q":"You and a friend both want to pick the game. What's a good compromise?","opts":["Play your game first, then theirs","You always choose","Stop being friends"],"why":"A compromise gives each person something they want."},{"t":"pick","q":"Which is an \"I statement\"?","opts":["\"I feel upset when my turn is skipped.\"","\"You always ruin everything!\"","\"You're mean.\""],"why":"I statements share feelings without blaming."},{"t":"tf","q":"Listening to your friend's side is part of solving a disagreement.","a":true,"why":"Understanding both sides helps you find a fair answer."},{"t":"do","q":"Mission: next time you disagree with someone, try saying \"I feel… when…\" and then listen to their side."}]},
"mt_w4nSIDhIgC":{"intro":"Every team needs different roles. Which one are you? 🧑‍🤝‍🧑","items":[{"t":"match","q":"Match each group role to what it does.","pairs":[["leader","helps guide the group and keep it on track"],["mediator","helps solve disagreements"],["idea-generator","comes up with lots of new ideas"],["supporter","encourages and helps others"]]},{"t":"tf","q":"A good group needs a mix of different roles.","a":true,"why":"Different strengths make a team stronger."},{"t":"pick","q":"Two group members are arguing. Who usually steps in to help?","opts":["the mediator","the idea-generator","nobody should"],"why":"Mediators help people agree."},{"t":"pick","q":"What would happen if everyone in a group wanted to be the leader?","opts":["It could be hard to get things done","The work would be perfect","Nothing would change"],"why":"Groups work best with a balance of roles."},{"t":"do","q":"Mission: next time you work in a group, notice which role you take. Tell a grown-up which role you'd like to try next."}]},
"mt_QxsoqVUt6u":{"intro":"Let's be awesome group members! 🏆","items":[{"t":"sort","q":"Helpful group member or not?","bins":["Helpful","Not helpful"],"items":[["sharing your ideas",0],["listening to others' ideas",0],["doing your fair share",0],["letting others do all the work",1],["laughing at someone's idea",1]]},{"t":"pick","q":"Your group has 4 jobs and 4 people. What is fair?","opts":["Each person does one job","One person does all 4","Nobody does any"],"why":"Sharing work fairly helps the group."},{"t":"pick","q":"A quiet group member hasn't shared yet. What could you say?","opts":["\"What do you think?\"","\"You don't have ideas.\"","Nothing, just keep going"],"why":"Inviting others helps everyone contribute."},{"t":"tf","q":"In a group, it's okay to support someone who is stuck.","a":true,"why":"Helping each other makes the whole group succeed."},{"t":"do","q":"Mission: work with a family member on a small project, like building with blocks. Make sure you both share ideas and jobs."}]},
"mt_rqLMfiw61L":{"intro":"Let's learn to speak up clearly and kindly! 🗣️","items":[{"t":"sort","q":"Is it assertive, aggressive, or passive?","bins":["Assertive","Aggressive","Passive"],"items":[["\"I'd like my pencil back, please.\"",0],["\"Give it back NOW or else!\"",1],["Saying nothing and feeling upset",2],["\"I don't want to play that. Can we try something else?\"",0],["Shoving someone out of line",1]]},{"t":"pick","q":"A friend keeps borrowing your stuff without asking. Which reply is assertive?","opts":["\"Please ask me first before you borrow my things.\"","\"You're a thief!\"","Never mention it"],"why":"Assertive means clear and respectful."},{"t":"tf","q":"Being assertive means you always get your way.","a":false,"why":"It means expressing your needs respectfully, not forcing others."},{"t":"pick","q":"Which body language goes with assertive talk?","opts":["Standing tall with a calm voice","Yelling and pointing","Mumbling at the floor"],"why":"Calm, confident body language matches assertive words."},{"t":"do","q":"Mission: practice an assertive sentence with a grown-up, like \"I feel… and I need…\" Use a calm, clear voice."}]},
"mt_33zncDHC3N":{"intro":"Feedback helps everyone grow. Let's practice giving and getting it! 🌟","items":[{"t":"pick","q":"Which is helpful feedback on a friend's story?","opts":["\"Your opening is exciting! Maybe add more about the ending.\"","\"It's bad.\"","\"It's perfect, don't change anything.\""],"why":"Good feedback names what works and one clear way to improve."},{"t":"pick","q":"Someone gives you feedback about your drawing. What is a good response?","opts":["\"Thanks, I'll think about that.\"","\"You don't know anything!\"","Crumple it up"],"why":"Feedback is a gift that can help you improve."},{"t":"tf","q":"Good feedback is specific, not just \"good\" or \"bad.\"","a":true,"why":"Specific feedback shows exactly what to keep or change."},{"t":"sort","q":"Constructive or hurtful?","bins":["Constructive","Hurtful"],"items":[["\"Your colors are bright. Try neater lines next time.\"",0],["\"That looks like a baby drew it.\"",1],["\"I liked your topic. The middle confused me a little.\"",0],["\"Why do you even try?\"",1]]},{"t":"do","q":"Mission: give a family member feedback on something they made. Name one thing you liked and one kind idea to try."}]},
"mt_AbnwmKD8oe":{"intro":"Let's learn to be a peacemaker for others! 🕊️","items":[{"t":"order","q":"Put these mediator steps in order.","steps":["Help both friends calm down","Let each person tell their side","Help them see each other's feelings","Guide them to find a solution"]},{"t":"pick","q":"As a mediator, which should you do?","opts":["Stay fair and listen to both sides","Pick your best friend's side","Tell them to stop being babies"],"why":"Mediators stay neutral and fair."},{"t":"tf","q":"A mediator decides who is right and punishes the other person.","a":false,"why":"A mediator helps both people find their own solution."},{"t":"pick","q":"Two friends both want the ball. What could a mediator ask?","opts":["\"What ideas do you both have to share it?\"","\"Who's stronger?\"","\"Why are you both so annoying?\""],"why":"Asking for ideas helps them solve it together."},{"t":"do","q":"Mission: next time two people (maybe siblings!) disagree, try asking each to share their side calmly. Then ask, \"What could work for both of you?\""}]},
"mt_z98J_Zg2L3":{"intro":"Let's look in the mirror at how we act with others. 🪞","items":[{"t":"pick","q":"You notice you often interrupt friends when you're excited. What's a good next step?","opts":["Practice waiting for them to finish","Decide it's their fault","Stop talking to friends"],"why":"Noticing a pattern helps you change it."},{"t":"tf","q":"Thinking about your own part in an argument can help fix friendships.","a":true,"why":"Reflection helps you understand and grow."},{"t":"pick","q":"Which question helps you reflect on a friendship?","opts":["\"What do I bring to this friendship?\"","\"How can I win every argument?\"","\"Why is everyone else wrong?\""],"why":"Good reflection looks at your own actions too."},{"t":"sort","q":"Healthy or unhealthy relationship pattern?","bins":["Healthy","Unhealthy"],"items":[["saying sorry when you're wrong",0],["always needing to be in charge",1],["listening when friends share",0],["only calling friends when you need something",1]]},{"t":"do","q":"Mission: write down one thing you do well as a friend and one thing you'd like to work on. Share it with a grown-up."}]},
"mt_nqM2OW0Qlm":{"intro":"Let's decode hidden messages and group behavior! 🧩","items":[{"t":"pick","q":"A friend says \"Whatever, it's fine\" with crossed arms and a flat voice. What's the likely subtext?","opts":["They're actually upset","They're totally happy","They're hungry"],"why":"Subtext is the hidden meaning beneath the words."},{"t":"pick","q":"Treating people in your own group better than outsiders is called…","opts":["in-group bias","teamwork","empathy"],"why":"In-group bias favors \"us\" over \"them.\""},{"t":"tf","q":"People sometimes go along with a group even when they privately disagree.","a":true,"why":"This is called conformity, and group pressure can be powerful."},{"t":"pick","q":"Your friend group starts ignoring a classmate for no reason. What's a strong choice?","opts":["Keep being friendly to the classmate","Join in to fit in","Pretend you didn't notice"],"why":"You can resist unfair group behavior."},{"t":"match","q":"Match each term to its meaning.","pairs":[["social cue","a signal like tone or body language"],["out-group","people seen as outside your group"],["conformity","changing behavior to match a group"]]}]},
"mt_NCrbQe0LdB":{"intro":"Honest talk can fix problems without hurting people. Let's practice! 🛠️","items":[{"t":"order","q":"Put the four steps of non-violent communication in order.","steps":["Observation: describe what happened","Feeling: say how you feel","Need: name what you need","Request: ask for a specific action"]},{"t":"pick","q":"Which statement addresses the problem without attacking the person?","opts":["\"When plans get canceled last minute, I feel let down.\"","\"You're so selfish and flaky.\"","\"You always ruin everything.\""],"why":"Focusing on the action, not the person, keeps talk respectful."},{"t":"pick","q":"Which is an observation, not a judgment?","opts":["\"You arrived 20 minutes after we agreed.\"","\"You're lazy.\"","\"You don't care about me.\""],"why":"Observations are facts anyone could see."},{"t":"tf","q":"A real apology names what you did and how you'll make it right.","a":true,"why":"Specific apologies help repair trust."},{"t":"pick","q":"Which is a clear request?","opts":["\"Could you text me if you'll be late?\"","\"Just be better.\"","\"Stop being you.\""],"why":"Requests should be specific and doable."}]},
"mt_8StiXnYq1u":{"intro":"There are many ways to lead. Let's explore leadership styles! 🧭","items":[{"t":"match","q":"Match each leadership style to its description.","pairs":[["directive","the leader makes clear decisions and gives instructions"],["democratic","the group votes or shares in decisions"],["servant","the leader focuses on helping the team grow"],["transformational","the leader inspires a big shared vision"]]},{"t":"pick","q":"There's a fire drill and everyone must exit quickly. Which style fits best?","opts":["directive","democratic","no leadership"],"why":"In emergencies, clear instructions keep people safe."},{"t":"pick","q":"Your class is choosing a field trip and wants everyone's ideas. Which style fits?","opts":["democratic","directive","transformational"],"why":"Democratic leadership gathers everyone's input."},{"t":"tf","q":"You can influence others even without an official leadership title.","a":true,"why":"Influence comes from your actions, ideas, and example."},{"t":"tf","q":"One leadership style is always best for every situation.","a":false,"why":"Good leaders choose the style that fits the situation."}]},
"mt_UHQfb-n-w3":{"intro":"Every choice leads to something. Let's think ahead! ➡️","items":[{"t":"match","q":"Match each action to what might happen next.","pairs":[["leaving toys on the stairs","someone could trip"],["sharing your snack 🍪","your friend feels happy"],["not brushing teeth 🦷","you could get cavities"],["watering a plant 🌱","the plant grows"]]},{"t":"pick","q":"If you leave your crayons out in the rain, what might happen?","opts":["They get wet and ruined","They turn into pencils","Nothing at all"],"why":"Actions have consequences."},{"t":"tf","q":"Our choices can affect other people, not just us.","a":true,"why":"What we do can make others feel happy or sad."},{"t":"pick","q":"You want to throw a ball inside near a lamp 💡. What should you think first?","opts":["\"What might happen if I do this?\"","\"Who can I throw it at?\"","\"How hard can I throw?\""],"why":"Thinking first helps you make good choices."},{"t":"do","q":"Mission: before you choose something today, say out loud, \"If I do this, then…\" and tell a grown-up what you thought."}]},
"mt_q3vRl4dddK":{"intro":"Let's learn how to stay safe every day! 🦺","items":[{"t":"order","q":"Put these steps for crossing a street in order.","steps":["Stop at the curb","Look left, right, and left again","Listen for cars","Walk across when it's clear"]},{"t":"pick","q":"A stranger offers you candy and a ride. What should you do?","opts":["Say no, get away, and tell a trusted adult","Get in the car","Take the candy and stay"],"why":"Never go with strangers. Tell a grown-up you trust."},{"t":"tf","q":"It's safe to swim without a grown-up watching.","a":false,"why":"Always swim with an adult nearby. 🏊"},{"t":"pick","q":"Someone online asks for your home address. What should you do?","opts":["Don't tell them and show a grown-up","Tell them right away","Send a photo of your house"],"why":"Keep personal information private online."},{"t":"do","q":"Mission: with a grown-up, list three trusted adults you can go to for help. Practice saying your grown-up's phone number."}]},
"mt_Wc6cOTQ1bA":{"intro":"Let's think about right and wrong choices! ✅","items":[{"t":"sort","q":"Right choice or wrong choice?","bins":["Right ✅","Wrong ❌"],"items":[["telling the truth",0],["hitting someone",1],["taking a toy without asking",1],["saying sorry",0],["helping clean up",0]]},{"t":"pick","q":"You broke a cup by accident ☕. What is the honest thing to do?","opts":["Tell a grown-up what happened","Hide the pieces","Blame your sister"],"why":"Being honest is the right choice, even when it's hard."},{"t":"pick","q":"You find a toy that isn't yours at school. What should you do?","opts":["Give it to the teacher","Keep it","Throw it away"],"why":"Respecting other people's things is right."},{"t":"tf","q":"It's okay to hurt someone if they hurt you first.","a":false,"why":"Hurting back isn't okay. Tell a grown-up instead."},{"t":"pick","q":"Your friend is sad because no one will play. What is the right choice?","opts":["Invite them to play","Laugh","Run away"],"why":"Kindness is always a good choice."}]},
"mt_rkrG2w7WXI":{"intro":"Why do we have rules? Let's find out! 📏","items":[{"t":"match","q":"Match each rule to why we have it.","pairs":[["walk, don't run, in the hallway","to keep people safe"],["take turns on the slide","to make things fair"],["raise your hand to speak ✋","so everyone can be heard"]]},{"t":"tf","q":"Rules help groups work well together.","a":true,"why":"Rules keep people safe and things fair."},{"t":"pick","q":"What could happen with no rules in a game?","opts":["People might argue about what's fair","The game would be more fair","Everyone would always win"],"why":"Rules help everyone know how to play."},{"t":"pick","q":"Why do we wear a seat belt in the car? 🚗","opts":["To stay safe","To look cool","Because it's comfy"],"why":"Seat belts protect us in a crash."},{"t":"do","q":"Mission: make up one rule for your family with a grown-up. Talk about why it helps."}]},
"mt_uTKgmWqSoI":{"intro":"Let's learn words for good choices and staying safe! 🛡️","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["choice","something you decide"],["consequence","what happens because of an action"],["honest","telling the truth"],["trusted adult","a grown-up who keeps you safe"]]},{"t":"pick","q":"Which word fits? \"Wearing a helmet keeps me ___.\" 🚲","opts":["safe","unfair","dishonest"],"why":"Helmets protect your head."},{"t":"pick","q":"Everyone got the same number of turns. That was…","opts":["fair","unsafe","a rule-break"],"why":"Fair means treating people the right way."},{"t":"tf","q":"A rule is something that tells us how to behave.","a":true,"why":"Rules guide our actions."},{"t":"pick","q":"Which is a trusted adult?","opts":["your teacher","a stranger at the park","someone you met online"],"why":"Trusted adults are people you know who care for you."}]},
"mt_zIzJGkaj0Q":{"intro":"Let's be good citizens online! 💻","items":[{"t":"sort","q":"Safe to share online, or keep private?","bins":["Okay to share","Keep private 🔒"],"items":[["your favorite animal",0],["your home address",1],["your password",1],["a drawing (with permission)",0],["your phone number",1]]},{"t":"tf","q":"The people behind screens are real people with real feelings.","a":true,"why":"Mean words online hurt just as much as in person."},{"t":"pick","q":"Someone posts a mean comment about your friend. What can you do?","opts":["Don't join in and tell a trusted adult","Add another mean comment","Share it with everyone"],"why":"Being kind and getting help is good digital citizenship."},{"t":"pick","q":"Before you post a comment, ask yourself…","opts":["\"Is it kind, true, and helpful?\"","\"Will it get the most likes?\"","\"Is it the funniest insult?\""],"why":"Think before you post."},{"t":"pick","q":"Which is a strong password idea?","opts":["A long mix of words and numbers only you know","Your first name","123456"],"why":"Long, hard-to-guess passwords keep accounts safe."}]},
"mt_yCmYV9ruQu":{"intro":"When you see unkindness, you can be an upstander! 🦸","items":[{"t":"sort","q":"Bystander or upstander?","bins":["Bystander","Upstander"],"items":[["watching and doing nothing",0],["telling a teacher",1],["inviting the left-out kid to play",1],["laughing along",0],["saying \"Stop, that's not okay\"",1]]},{"t":"pick","q":"What is an upstander?","opts":["Someone who takes action to help","Someone who stands on a chair","Someone who joins the teasing"],"why":"Upstanders help when they see unkindness."},{"t":"tf","q":"Getting help from a trusted adult is a way to be an upstander.","a":true,"why":"You don't have to handle it alone."},{"t":"pick","q":"Kids are teasing someone at lunch. What's a safe upstander move?","opts":["Sit with the person being teased","Join the teasing","Pretend you didn't see"],"why":"Showing support helps the person feel less alone."},{"t":"do","q":"Mission: with a grown-up, practice two things you could say or do if you see someone being treated unkindly."}]},
"mt_RhntJz7p_6":{"intro":"Stop, think, then choose! Let's practice smart decisions. 🚦","items":[{"t":"order","q":"Put the decision steps in order.","steps":["Stop","Think of your options","Think about what could happen","Choose the best one"]},{"t":"pick","q":"Your friend wants you to skip homework to play. What's the first step?","opts":["Stop and think","Say yes right away","Run outside"],"why":"Stopping first gives you time to think."},{"t":"pick","q":"You have two options: play now or finish chores first. Which question helps most?","opts":["\"What will happen with each choice?\"","\"Which is more fun right now?\"","\"What would a cartoon do?\""],"why":"Thinking about consequences helps you choose well."},{"t":"tf","q":"Good decisions always have to be made super fast.","a":false,"why":"Taking time to think usually leads to better choices."},{"t":"do","q":"Mission: next time you have a choice, say \"Stop, think, choose\" out loud. Tell a grown-up your options and what you chose."}]},
"mt_I9iSzpGRn5":{"intro":"Let's understand bullying and how to stop it. 🛑","items":[{"t":"pick","q":"What makes something bullying?","opts":["It's repeated and meant to hurt","It happened once by accident","Two friends disagree once"],"why":"Bullying is on purpose and happens again and again."},{"t":"match","q":"Match each example to the type of bullying.","pairs":[["pushing or hitting","physical"],["name-calling","verbal"],["leaving someone out on purpose","social"],["mean messages online","cyberbullying"]]},{"t":"tf","q":"Spreading rumors about someone can be bullying.","a":true,"why":"Social bullying hurts relationships and feelings."},{"t":"pick","q":"If you're being bullied, what should you do?","opts":["Tell a trusted adult","Keep it secret","Bully them back"],"why":"Trusted adults can help stop bullying."},{"t":"tf","q":"A friend accidentally bumping you once in line is bullying.","a":false,"why":"Accidents aren't bullying. Bullying is repeated and on purpose."}]},
"mt_h-z88yf9Pn":{"intro":"Let's learn the words of good citizens! 🏛️","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["upstander","someone who acts to help"],["peer pressure","feeling pushed by friends to do something"],["responsibility","a duty you are expected to do"],["cyberbullying","bullying using phones or the internet"]]},{"t":"pick","q":"Everyone has the ___ to feel safe at school.","opts":["right","consequence","peer pressure"],"why":"A right is something everyone deserves."},{"t":"pick","q":"Using the internet safely and kindly is called…","opts":["digital citizenship","cyberbullying","peer pressure"],"why":"Digital citizens act responsibly online."},{"t":"tf","q":"A bystander is someone who sees bullying but doesn't do anything.","a":true,"why":"Upstanders take action; bystanders don't."},{"t":"pick","q":"Your friends dare you to break a rule. This is…","opts":["peer pressure","a right","digital citizenship"],"why":"Peer pressure is when peers push you to do something."}]},
"mt_h_shhH-6DC":{"intro":"Being part of a community means rights AND responsibilities! 🏘️","items":[{"t":"sort","q":"Is it a right or a responsibility?","bins":["Right","Responsibility"],"items":[["to be treated with respect",0],["to treat others with respect",1],["to feel safe",0],["to follow class rules",1],["to an education",0],["to pick up your litter",1]]},{"t":"tf","q":"Rights come with responsibilities.","a":true,"why":"If I have a right to respect, I must respect others too."},{"t":"pick","q":"Which shows a responsibility to your community?","opts":["Volunteering at a park cleanup","Leaving trash on the sidewalk","Ignoring neighbors in need"],"why":"Helping your community is part of being a good member."},{"t":"pick","q":"If everyone has the right to feel safe, what is your responsibility?","opts":["Not to make others feel unsafe","To stay home forever","Nothing"],"why":"Protecting others' rights is a shared duty."},{"t":"do","q":"Mission: find one way to help your community this week, like picking up litter or helping a neighbor. Tell a grown-up how it went."}]},
"mt_6xj94tmpi-":{"intro":"Some choices are tricky. Let's think through tough ones! 🤔","items":[{"t":"tf","q":"Some ethical choices have no perfect answer.","a":true,"why":"Sometimes every option has good and bad sides."},{"t":"pick","q":"Your friend made a cake 🎂 that tastes bad and asks if you like it. Which answer balances honesty and kindness?","opts":["\"I love that you made it! The frosting was my favorite part.\"","\"It's disgusting.\"","\"Best cake ever!\" even though it isn't"],"why":"You can be honest and kind at the same time."},{"t":"pick","q":"When facing a hard choice, what helps?","opts":["Thinking about who is affected and what's fair","Flipping a coin every time","Doing what's easiest for you"],"why":"Weighing effects on others leads to more thoughtful choices."},{"t":"tf","q":"If two people disagree on a tough ethical question, one must be a bad person.","a":false,"why":"Reasonable people can disagree."},{"t":"pick","q":"You promised to keep a secret, but your friend says they're in danger. What should you do?","opts":["Tell a trusted adult","Keep the promise no matter what","Tell the whole class"],"why":"Safety matters more than keeping a secret."}]},
"mt_RNeEF1JU4J":{"intro":"Let's be ethics investigators on real-world issues! 🌎","items":[{"t":"pick","q":"A team uses a banned trick to win a game. What ethical issue is this?","opts":["Fairness in sport","Recycling","Bedtime"],"why":"Cheating is unfair to the other team."},{"t":"sort","q":"Environmentally responsible or not?","bins":["Responsible","Not responsible"],"items":[["using a refillable water bottle",0],["littering at the beach",1],["turning off lights when leaving",0],["dumping oil down a drain",1]]},{"t":"pick","q":"Is it ethical to share a classmate's photo online without asking?","opts":["No, you should ask permission first","Yes, always","Only if it's funny"],"why":"Respecting privacy is a key part of digital ethics."},{"t":"tf","q":"Looking at an issue from many sides helps you make a fair judgment.","a":true,"why":"Different perspectives reveal more of the story."},{"t":"pick","q":"A company makes cheap toys but pays workers very little. What question should we ask?","opts":["\"Are the workers treated fairly?\"","\"What color are the toys?\"","\"Who has the best logo?\""],"why":"Ethics means thinking about how people are affected."}]},
"mt_JivEBTD_KV":{"intro":"You can stand strong when friends push you! 💪","items":[{"t":"pick","q":"What is peer pressure?","opts":["Feeling pushed by friends to do something","A kind of tire pressure","When a teacher gives homework"],"why":"Peers are people your age who can influence you."},{"t":"sort","q":"Good way to resist pressure or not?","bins":["Good strategy","Not helpful"],"items":[["say \"No thanks\" firmly",0],["suggest a different activity",0],["walk away",0],["go along so they like you",1],["hang out with friends who respect you",0]]},{"t":"tf","q":"Peer pressure can be positive, like friends encouraging you to try out for a team.","a":true,"why":"Peers can push us toward good things too."},{"t":"pick","q":"Friends dare you to take something from a store. What's a strong reply?","opts":["\"No way. I'm not doing that.\"","\"Okay, just this once.\"","\"Only if you do it first.\""],"why":"A clear no shows you make your own choices."},{"t":"do","q":"Mission: with a grown-up, role-play saying no to a pressure situation. Practice a firm voice and a different idea."}]},
"mt_JiZ3H90Xg8":{"intro":"Let's explore risk, uncertainty, and the tricks our brains play! 🎲","items":[{"t":"pick","q":"Rolling a fair 6-sided die and getting a 6 has a known chance of 1 in 6. This is…","opts":["risk","uncertainty","a bias"],"why":"Risk means the probabilities are known."},{"t":"pick","q":"Guessing whether a brand-new app will be popular next year, with no data, is…","opts":["uncertainty","risk","a sure thing"],"why":"Uncertainty means the chances are unknown."},{"t":"match","q":"Match each bias to its description.","pairs":[["confirmation bias","only noticing info that agrees with you"],["availability bias","judging by examples that come to mind easily"],["anchoring","relying too much on the first number you hear"]]},{"t":"tf","q":"After a coin lands heads 5 times in a row, tails is now more likely.","a":false,"why":"Each fair flip is still 50/50. Thinking otherwise is the gambler's fallacy."},{"t":"pick","q":"After seeing news about a shark attack, Kai thinks sharks are a huge danger at every beach. Which bias is this?","opts":["availability bias","anchoring","no bias"],"why":"Vivid stories feel more common than they really are."}]},
"mt_WtO50EZQkf":{"intro":"Let's be smart about who we are online and what we believe! 📱","items":[{"t":"pick","q":"Recommendation algorithms usually show you…","opts":["more of what you already click and watch","a perfectly balanced mix of views","only random posts"],"why":"They learn from your clicks, which can create echo chambers."},{"t":"tf","q":"Misinformation can spread faster online than corrections.","a":true,"why":"Surprising or emotional posts get shared quickly."},{"t":"order","q":"Put these steps for checking a surprising post in order.","steps":["Pause before sharing","Check who posted it","Look for other trusted sources","Decide whether to share"]},{"t":"pick","q":"Which shows a healthy online identity?","opts":["Acting online the way you would face to face","Being cruel because no one knows you","Pretending to be someone else to trick people"],"why":"Consistency online and offline builds trust."},{"t":"pick","q":"A video claims a celebrity said something shocking, but no news site reports it. What's smart?","opts":["Treat it with doubt until confirmed","Share it immediately","Believe it because it has many views"],"why":"Lots of views doesn't make something true."}]},
"mt_LPYPuSaxv_":{"intro":"How do we decide what's right? Let's meet three big ideas! ⚖️","items":[{"t":"match","q":"Match each ethical framework to its main idea.","pairs":[["consequentialism","judge actions by their outcomes"],["deontology","judge actions by duties and rules"],["virtue ethics","ask what a good person would do"]]},{"t":"pick","q":"\"Lying is always wrong, even to make someone feel better.\" Which framework fits?","opts":["deontology","consequentialism","virtue ethics"],"why":"Deontology focuses on following moral rules."},{"t":"pick","q":"\"Choose the option that helps the most people.\" Which framework fits?","opts":["consequentialism","deontology","virtue ethics"],"why":"Consequentialism weighs outcomes and overall welfare."},{"t":"pick","q":"\"What would an honest, brave, and kind person do here?\" Which framework fits?","opts":["virtue ethics","deontology","consequentialism"],"why":"Virtue ethics focuses on good character."},{"t":"tf","q":"Different frameworks can lead to different answers to the same dilemma.","a":true,"why":"That's why moral reasoning means comparing viewpoints."}]},
"mt_69hFD2NgGe":{"intro":"Let's name our feelings! 😊😢😠","items":[{"t":"match","q":"Match each face to its feeling.","pairs":[["😊","happy"],["😢","sad"],["😠","angry"],["😨","scared"]]},{"t":"pick","q":"Your ice cream fell on the ground 🍦. How might you feel?","opts":["sad","happy","sleepy"],"why":"It's normal to feel sad when something goes wrong."},{"t":"pick","q":"You're going to a birthday party 🎈! How might you feel?","opts":["excited","angry","bored"],"why":"Fun things can make us feel excited."},{"t":"tf","q":"Naming your feeling can help you feel better.","a":true,"why":"Saying \"I feel sad\" is the first step to feeling better."},{"t":"do","q":"Mission: tell a grown-up, \"Right now I feel…\" and name your feeling. Try it again at bedtime!"}]},
"mt_H4YZ1rSKP3":{"intro":"Let's learn words that help us understand ourselves! 🔎","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["reflect","think back carefully"],["trigger","something that sets off a feeling"],["pattern","something that happens again and again"],["notice","pay attention to something"]]},{"t":"pick","q":"Knowing your own feelings and habits is called…","opts":["self-awareness","self-service","selfie"],"why":"Self-awareness means understanding yourself."},{"t":"pick","q":"\"I thought she ignored me, but she didn't hear me.\" My first idea was an…","opts":["assumption","impact","pattern"],"why":"An assumption is something you believe without checking."},{"t":"tf","q":"Impact means the effect your actions have on others.","a":true,"why":"Your words and actions have an impact."},{"t":"pick","q":"Which word means how someone sees things?","opts":["perspective","trigger","pattern"],"why":"Perspective is a point of view."}]},
"mt_TU3BcLOgiV":{"intro":"Feelings and actions are different. You get to choose what you do! 🎮","items":[{"t":"tf","q":"You can feel angry without hitting anyone.","a":true,"why":"Feelings are okay; we choose our actions."},{"t":"sort","q":"Is it a feeling or an action?","bins":["Feeling","Action"],"items":[["angry",0],["stomping feet",1],["sad",0],["crying",1],["jealous",0],["taking a deep breath",1]]},{"t":"pick","q":"Your brother knocked over your blocks and you feel mad 😠. What is a good action?","opts":["Say \"I feel mad\" and take a breath","Knock over his stuff","Yell at him"],"why":"You can feel mad and still choose a calm action."},{"t":"pick","q":"Which sentence is true?","opts":["All feelings are okay, but not all actions are okay","Some feelings are bad","Feelings must always be acted on right away"],"why":"Feelings are normal; actions need good choices."},{"t":"do","q":"Mission: next time you have a big feeling, try waiting and counting to 5 before you act. Tell a grown-up what happened."}]},
"mt_H8dEMH_wik":{"intro":"Let's be detectives and spot our own reaction patterns! 🕵️","items":[{"t":"pick","q":"Liam gets snappy every time he's really tired 😴. What's his pattern?","opts":["He reacts with grumpiness when tired","He's always grumpy","He's never grumpy"],"why":"Noticing when you react helps you plan."},{"t":"tf","q":"Knowing your patterns can help you make better choices.","a":true,"why":"If you know being hungry makes you cranky, you can eat a snack first."},{"t":"sort","q":"Which could be a trigger for a strong reaction?","bins":["Possible trigger","Not a trigger"],"items":[["being left out",0],["feeling tired",0],["being put on the spot in class",0],["the color of the sky",1]]},{"t":"pick","q":"Emma always cries when called on suddenly. What could help?","opts":["Ask the teacher for a heads-up before being called on","Never go to school","Pretend it doesn't happen"],"why":"Planning around a known pattern helps."},{"t":"do","q":"Mission: think about a time you got upset. Were you tired, hungry, or left out? Tell a grown-up a pattern you notice in yourself."}]},
"mt_rpug2tkYhb":{"intro":"What you mean and how it lands can be different. Let's explore! 🎯","items":[{"t":"pick","q":"Tom jokes that Ana's drawing looks \"like a toddler made it.\" He meant it as fun, but Ana looks hurt. What was the impact?","opts":["Ana felt hurt","Ana felt proud","No impact"],"why":"Impact is how it felt to the other person, even if you meant well."},{"t":"tf","q":"If you didn't mean to hurt someone, then they shouldn't feel hurt.","a":false,"why":"Intent and impact can be different. Their feelings are still real."},{"t":"pick","q":"You hurt a friend by accident. What is a good response?","opts":["\"I didn't mean it, but I'm sorry it hurt you.\"","\"It was just a joke, get over it.\"","Walk away"],"why":"Owning the impact helps repair friendships."},{"t":"match","q":"Match each word to its meaning.","pairs":[["intent","what you meant to do"],["impact","how it affected someone"],["repair","fixing a hurt"]]},{"t":"do","q":"Mission: think of something you said this week. How might it have felt to the other person? Talk about it with a grown-up."}]},
"mt_Mb1JUJmnbX":{"intro":"First impressions can be wrong. Let's look again! 👀","items":[{"t":"pick","q":"A classmate doesn't wave back to you. Which is a possible explanation?","opts":["They didn't see you","They definitely hate you","They are planning something mean"],"why":"There are often many reasons for what people do."},{"t":"tf","q":"An assumption is the same as a fact.","a":false,"why":"An assumption is a guess. A fact is proven true."},{"t":"sort","q":"Fact or assumption?","bins":["Fact","Assumption"],"items":[["Jake didn't sit with me at lunch",0],["Jake is mad at me",1],["The new kid didn't talk in class",0],["The new kid is rude",1]]},{"t":"pick","q":"Your friend seems short with you today. What's a good next step?","opts":["Ask, \"Is everything okay?\"","Decide they don't like you anymore","Be mean back"],"why":"Asking checks your first guess."},{"t":"pick","q":"Why should we question first impressions?","opts":["We might not have the whole story","First impressions are always right","It's fun to be confused"],"why":"Getting more info helps us understand others."}]},
"mt_bkMDDstwwG":{"intro":"Look how far you've come! Let's reflect on growth. 🌱","items":[{"t":"tf","q":"Something that's hard for you now can get easier with time and practice.","a":true,"why":"Your challenges are not fixed."},{"t":"pick","q":"Which thought shows noticing your own growth?","opts":["\"Last year I couldn't do this, and now I can!\"","\"I'll never get better.\"","\"I've always been this way.\""],"why":"Comparing with your past self shows real progress."},{"t":"pick","q":"What builds real self-confidence?","opts":["Seeing evidence of how you've improved","Being told you're perfect","Never trying anything hard"],"why":"Proof of your growth builds lasting confidence."},{"t":"pick","q":"Who is the most helpful person to compare yourself to?","opts":["Your past self","The best kid in class","A famous athlete"],"why":"Your own progress tells your real story."},{"t":"do","q":"Mission: look at old schoolwork or a drawing from last year. Write or tell a grown-up three ways you've grown since then."}]},
"mt_aS-Gdh-MHx":{"intro":"Changes happen to everyone. Let's learn how to cope! 🦋","items":[{"t":"tf","q":"Change is a normal part of life.","a":true,"why":"Everyone goes through changes like new schools or new babies."},{"t":"sort","q":"Which are life changes?","bins":["Life change","Not a big change"],"items":[["moving to a new house 🏠",0],["a new baby in the family 👶",0],["starting a new school",0],["eating cereal for breakfast",1]]},{"t":"pick","q":"You're nervous about getting a new teacher. What can help?","opts":["Talk to a grown-up about your feelings","Hide under the bed","Pretend you're not nervous"],"why":"Talking about feelings helps with changes."},{"t":"pick","q":"Which thought helps during a change?","opts":["\"It feels new now, but I'll get used to it.\"","\"Everything is ruined forever.\"","\"I can't do anything.\""],"why":"Change gets easier with time."},{"t":"do","q":"Mission: think of a change that happened to you. Draw a picture of how you felt then and how you feel now."}]},
"mt_UGf6jICEhs":{"intro":"Mistakes help us learn! Let's find out how. 🌟","items":[{"t":"tf","q":"Grown-ups make mistakes too.","a":true,"why":"Everyone makes mistakes. It's how we learn."},{"t":"pick","q":"You spelled a word wrong ✏️. What should you do?","opts":["Fix it and keep going","Rip up the paper","Give up writing"],"why":"Mistakes are chances to learn."},{"t":"pick","q":"Which thought is helpful after a mistake?","opts":["\"Oops! Now I know what to try next.\"","\"I'm bad at everything.\"","\"I'll never try again.\""],"why":"Seeing mistakes as learning helps you grow."},{"t":"tf","q":"If you make a mistake, you are not smart.","a":false,"why":"Making mistakes is part of getting smarter."},{"t":"do","q":"Mission: ask a grown-up to tell you about a mistake they made and what they learned from it."}]},
"mt_nNDX_jZ-cb":{"intro":"Waiting can be hard, but you can do it! ⏳","items":[{"t":"pick","q":"You want a cookie 🍪 but dinner is in 10 minutes. What shows patience?","opts":["Wait until after dinner","Grab it and run","Cry loudly"],"why":"Waiting is part of being patient."},{"t":"sort","q":"Patient or not patient?","bins":["Patient 😊","Not patient"],"items":[["waiting your turn on the slide",0],["pushing to the front of the line",1],["singing a song while you wait",0],["yelling \"Hurry up!\"",1]]},{"t":"pick","q":"What can help you wait?","opts":["Do something else fun while waiting","Stare at the clock and whine","Keep asking \"Is it time yet?\""],"why":"Keeping busy makes waiting easier."},{"t":"tf","q":"Sometimes waiting means you get something even better later.","a":true,"why":"Saving a treat or your turn can be worth it."},{"t":"do","q":"Mission: play a waiting game with a grown-up. Wait for a small treat for 5 minutes while doing something fun, like drawing."}]},
"mt_Iwg2diBSyW":{"intro":"Let's learn ways to calm down when big feelings come! 🌬️","items":[{"t":"sort","q":"Calming strategy or not?","bins":["Calming 😌","Not calming"],"items":[["taking deep breaths",0],["counting to ten",0],["going to a quiet space",0],["throwing toys",1],["screaming at someone",1]]},{"t":"pick","q":"You feel very upset 😣. What can you try first?","opts":["Take three slow, deep breaths","Throw your toys","Run into the street"],"why":"Deep breaths help your body calm down."},{"t":"tf","q":"Calming down can help you think more clearly.","a":true,"why":"When you're calm, it's easier to solve problems."},{"t":"pick","q":"Smell the flower 🌸, blow out the candle 🕯️. This is a way to…","opts":["breathe slowly","count numbers","sing a song"],"why":"It's a fun way to practice deep breathing."},{"t":"do","q":"Mission: practice \"smell the flower, blow out the candle\" breathing 5 times with a grown-up."}]},
"mt_SeNxOZTHCN":{"intro":"Words help us handle big feelings! 💬","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["calm","quiet and peaceful inside"],["overwhelmed","too many feelings at once"],["strategy","a plan to help"],["patience","being able to wait"]]},{"t":"pick","q":"Which word fits? \"When I'm upset, I ___ slowly to feel better.\"","opts":["breathe","yell","run"],"why":"Breathing slowly helps us calm down."},{"t":"pick","q":"\"I can handle this hard thing.\" This means you can…","opts":["cope","quit","forget"],"why":"Cope means to handle something hard."},{"t":"tf","q":"Settle means to become calm and still.","a":true,"why":"After a big feeling, we can settle down."},{"t":"do","q":"Mission: next time you feel a big feeling, try saying it in words, like \"I feel overwhelmed. I need a strategy.\""}]},
"mt_miGrca8zaS":{"intro":"Big jobs get easier when we break them into steps! 🪜","items":[{"t":"order","q":"Cleaning a very messy room. Put these small steps in a sensible order.","steps":["Pick up clothes and put them in the hamper","Put toys back in their bins","Put books on the shelf","Celebrate your clean room! 🎉"]},{"t":"pick","q":"You have a big book report due. What's a smart first step?","opts":["Break it into small parts with a plan","Do it all the night before","Ignore it"],"why":"Small steps make big tasks manageable."},{"t":"tf","q":"Celebrating small steps can help you keep going.","a":true,"why":"Noticing progress keeps you motivated."},{"t":"pick","q":"Learning to ride a bike 🚲. Which is a smaller step?","opts":["Practice balancing first","Ride down a big hill on day one","Do tricks right away"],"why":"Small steps build to the big goal."},{"t":"do","q":"Mission: pick a big job at home. With a grown-up, list 3 to 5 small steps, then check each one off as you finish it."}]},
"mt_j8Pv3s7TZR":{"intro":"Different feelings need different tools. Let's choose wisely! 🧰","items":[{"t":"match","q":"Match each feeling to a helpful coping strategy.","pairs":[["angry 😠","take a break and breathe"],["sad 😢","talk to someone you trust"],["worried 😟","make a plan for what might happen"],["full of energy 🤸","go run or jump outside"]]},{"t":"tf","q":"The same coping strategy works for every feeling in every place.","a":false,"why":"Different situations need different strategies."},{"t":"pick","q":"You feel angry in class and can't leave the room. Which strategy fits?","opts":["Quietly take slow breaths","Run laps around the room","Shout into a pillow"],"why":"Some strategies work better in certain places."},{"t":"pick","q":"You're sad because your pet is sick. What might help most?","opts":["Hug a grown-up and talk about it","Run fast laps","Count to 100 quickly"],"why":"Sadness often needs comfort and talking."},{"t":"do","q":"Mission: make a list of three coping strategies for home and three for school. Share it with a grown-up."}]},
"mt_pAuo9Op89t":{"intro":"Your brain can grow like a muscle! 🧠💪","items":[{"t":"sort","q":"Growth mindset or fixed mindset?","bins":["Growth mindset","Fixed mindset"],"items":[["\"I can't do it YET.\"",0],["\"I'm just not a math person.\"",1],["\"Mistakes help me learn.\"",0],["\"If it's hard, I'm not smart.\"",1],["\"I'll try a different strategy.\"",0]]},{"t":"pick","q":"What is a growth mindset?","opts":["Believing abilities grow with effort and practice","Believing you're born smart or not","Believing plants grow fast"],"why":"With effort and good strategies, you can improve."},{"t":"tf","q":"Adding the word \"yet\" can change a fixed thought into a growth thought.","a":true,"why":"\"I can't do this yet\" means you're still learning."},{"t":"pick","q":"Change \"I'm bad at reading\" to a growth mindset thought.","opts":["\"I'm getting better at reading with practice.\"","\"I'll never read well.\"","\"Reading is pointless.\""],"why":"Growth thoughts focus on progress."},{"t":"do","q":"Mission: pick something hard for you. Practice it for 10 minutes and say, \"I'm getting better!\" Tell a grown-up how it went."}]},
"mt_35-DhMh_Yr":{"intro":"The words we say to ourselves matter! Let's practice kind self-talk. 🗯️","items":[{"t":"sort","q":"Helpful or unhelpful self-talk?","bins":["Helpful 😊","Unhelpful 😞"],"items":[["\"I can do hard things.\"",0],["\"I'm stupid.\"",1],["\"I'll try my best.\"",0],["\"I'll never get this.\"",1],["\"Everyone makes mistakes.\"",0]]},{"t":"pick","q":"Replace \"I'm going to fail this test\" with positive self-talk.","opts":["\"I studied, and I'll do my best.\"","\"I'm going to fail for sure.\"","\"Tests are dumb.\""],"why":"Encouraging words help you feel ready."},{"t":"tf","q":"Talking kindly to yourself can help you feel calmer and braver.","a":true,"why":"Positive self-talk helps manage tough moments."},{"t":"pick","q":"You miss a goal in soccer ⚽. What's helpful self-talk?","opts":["\"Next time I'll aim a little lower.\"","\"I'm the worst player ever.\"","\"I quit.\""],"why":"Helpful self-talk plans for next time."},{"t":"do","q":"Mission: write one positive self-talk sentence on a sticky note and put it where you'll see it every day."}]},
"mt_i1kk9HDctI":{"intro":"Let's learn the words of resilience! 🏔️","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["resilience","bouncing back after hard times"],["setback","something that slows your progress"],["regulate","manage or control your feelings"],["self-talk","the words you say to yourself"]]},{"t":"pick","q":"\"I can improve with practice.\" This is a…","opts":["growth mindset","fixed mindset","setback"],"why":"Growth mindset means abilities can grow."},{"t":"pick","q":"Something that sets off a strong feeling is a…","opts":["trigger","strategy","goal"],"why":"Triggers spark feelings or reactions."},{"t":"tf","q":"A fixed mindset means believing your abilities can't change.","a":true,"why":"Fixed mindset thinks talents are set."},{"t":"pick","q":"You lost a race but kept training and won the next one. You showed…","opts":["resilience","a trigger","a fixed mindset"],"why":"Resilience means recovering and keeping going."}]},
"mt_Jd2aWEUJ9G":{"intro":"Let's build your very own coping toolkit! 🧰","items":[{"t":"tf","q":"Coping strategies that work for your friend might not work best for you.","a":true,"why":"Everyone's toolkit is personal."},{"t":"sort","q":"Which go in a healthy coping toolkit?","bins":["Healthy tool","Unhealthy"],"items":[["drawing or journaling",0],["going for a walk",0],["talking to a trusted person",0],["taking it out on someone else",1],["listening to calming music",0],["bottling it up forever",1]]},{"t":"pick","q":"How can you tell if a coping strategy works for you?","opts":["Try it and notice how you feel after","Ask what's popular online","Use only one strategy forever"],"why":"Reflecting on results helps you choose."},{"t":"pick","q":"Why is it good to have several tools, not just one?","opts":["Different situations need different tools","More tools are heavier","One tool is always enough"],"why":"A good toolkit has options for many situations."},{"t":"do","q":"Mission: make a toolkit card listing your top 5 coping strategies. Put a star next to the one that works best at school."}]},
"mt_cJjnPjuvCU":{"intro":"Let's set goals and make a plan to reach them! 🎯","items":[{"t":"pick","q":"Which goal is most realistic and specific?","opts":["\"Read 20 minutes every night this month\"","\"Be the best reader in the world\"","\"Read more, maybe\""],"why":"Specific, realistic goals are easier to achieve."},{"t":"order","q":"Put the goal-setting steps in order.","steps":["Choose a goal","Make a plan","Track your progress","Adjust if it isn't working"]},{"t":"tf","q":"If your plan isn't working, it's okay to change it.","a":true,"why":"Adjusting your approach is part of reaching goals."},{"t":"pick","q":"You want to run a mile 🏃 without stopping. Which plan is best?","opts":["Run a little farther each week","Try a marathon tomorrow","Never practice"],"why":"Gradual steps help you reach big goals."},{"t":"do","q":"Mission: set one goal for the next two weeks. Write your plan and check your progress every few days with a grown-up."}]},
"mt_Amw5ikSSQI":{"intro":"Resilience means bouncing back like a rubber ball! 🏀","items":[{"t":"pick","q":"What is resilience?","opts":["Recovering from setbacks and keeping going","Never having any problems","Giving up when it's hard"],"why":"Resilient people bounce back from tough times."},{"t":"tf","q":"Resilience is a skill that can be practiced and grown.","a":true,"why":"Everyone can build resilience over time."},{"t":"pick","q":"Maya didn't make the team. What shows resilience?","opts":["Practice more and try again next season","Quit sports forever","Blame the coach"],"why":"Learning and trying again shows resilience."},{"t":"sort","q":"Which help build resilience?","bins":["Builds resilience","Doesn't help"],"items":[["having supportive people",0],["learning from setbacks",0],["positive self-talk",0],["avoiding every challenge",1],["telling yourself you're a failure",1]]},{"t":"do","q":"Mission: ask a grown-up about a time they bounced back from something hard. Share a time you did too."}]},
"mt_HoJGVsMO7H":{"intro":"Let's become masters of time and focus! ⏰","items":[{"t":"pick","q":"You have homework due tomorrow and a fun video to watch. Which should come first?","opts":["Homework","The video","Neither"],"why":"Prioritizing means doing the most important thing first."},{"t":"sort","q":"Helps focus or distracts?","bins":["Helps focus","Distraction"],"items":[["phone notifications 📱",1],["a quiet, tidy desk",0],["TV on in the background",1],["a timer for work sessions",0],["a to-do list",0]]},{"t":"tf","q":"Working in short focused bursts with breaks can help you concentrate.","a":true,"why":"Short sessions with breaks help many people stay focused."},{"t":"pick","q":"You have 3 tasks. One is due today, one tomorrow, and one next week. Which do you do first?","opts":["The one due today","The one due next week","The easiest one, no matter when it's due"],"why":"Urgent tasks usually come first."},{"t":"do","q":"Mission: make a to-do list for tomorrow. Number the tasks by importance and try a 20-minute focus timer for the first one."}]},
"mt_0VOZSVjo6c":{"intro":"Not all stress is bad! Let's sort good stress from bad stress. 🎢","items":[{"t":"match","q":"Match each term to its meaning.","pairs":[["eustress","helpful stress that motivates you"],["distress","harmful, overwhelming stress"],["cortisol","a stress hormone released by the body"],["fight-or-flight","the body's quick reaction to danger"]]},{"t":"sort","q":"Eustress or distress?","bins":["Eustress","Distress"],"items":[["excited jitters before a big game you've practiced for",0],["months of worry that keep you from sleeping",1],["a challenging but fun project",0],["feeling constantly overwhelmed by too many deadlines",1]]},{"t":"pick","q":"During the stress response, which body change usually happens?","opts":["Heart rate speeds up","Heart stops beating","Body temperature drops to freezing"],"why":"Adrenaline speeds up the heart to prepare the body for action."},{"t":"tf","q":"Long-lasting distress can affect sleep, mood, and health.","a":true,"why":"Chronic stress wears on the body and mind."},{"t":"pick","q":"Which strategy helps turn distress down?","opts":["Breaking work into steps and getting good sleep","Staying up all night worrying","Avoiding everyone"],"why":"Planning and rest help manage stress."}]},
"mt_0ewYhTSHtP":{"intro":"Let's crack the code of habits and motivation! 🔁","items":[{"t":"order","q":"Put the habit loop in order.","steps":["Cue","Routine","Reward"]},{"t":"match","q":"For the habit of reading at bedtime, match each part of the loop.","pairs":[["cue","putting on pajamas"],["routine","reading for 15 minutes"],["reward","feeling cozy and relaxed"]]},{"t":"sort","q":"Intrinsic or extrinsic motivation?","bins":["Intrinsic","Extrinsic"],"items":[["drawing because you love it",0],["cleaning your room to earn $5",1],["learning guitar because it's fun",0],["studying only to get a prize",1]]},{"t":"tf","q":"Linking a new habit to something you already do every day can make it easier to stick.","a":true,"why":"Existing routines can act as a cue for the new habit."},{"t":"pick","q":"Which is usually longer-lasting motivation?","opts":["intrinsic","extrinsic","neither ever lasts"],"why":"Doing something for its own sake tends to keep you going."}]},
"mt__J2BO4V95l":{"intro":"Hard times can help people grow in surprising ways. 🌻","items":[{"t":"match","q":"Match each area of growth to an example.","pairs":[["new perspective on life","appreciating small joys more"],["improved relationships","feeling closer to family who helped"],["personal strength","\"I handled that, so I can handle more\""]]},{"t":"tf","q":"Growing after adversity means the hard event was good or didn't hurt.","a":false,"why":"Pain is real. Growth can happen alongside it, not instead of it."},{"t":"pick","q":"Which helps people grow through adversity?","opts":["Support from others and reflecting on the experience","Pretending nothing happened","Facing everything alone"],"why":"Connection and reflection support growth."},{"t":"pick","q":"After a serious injury, an athlete starts mentoring younger players. This shows…","opts":["growth through adversity","giving up","a fixed mindset"],"why":"They found new meaning and purpose after a challenge."},{"t":"tf","q":"Growth after adversity often takes time.","a":true,"why":"Healing and growth happen gradually."}]}
});
